 const reorderWidget=(id:string,direction:'front'|'back')=>{const item=widgets.find(w=>w.id===id);if(!item)return;onChange(direction==='front'?[...widgets.filter(w=>w.id!==id),item]:[item,...widgets.filter(w=>w.id!==id)])};
